export function FormGroup({
  label = "{{label}}",
  helper = "{{helper}}",
  placeholder = "{{placeholder}}",
  accent = "{{accent}}",
  required = {{required}},
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 280 }}>
      <label htmlFor="fg-react-1" style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}{required && " *"}</label>
      <input id="fg-react-1" type="text" placeholder={placeholder} required={required} aria-describedby="fg-react-help-1" style={{
        width: "100%", boxSizing: "border-box", padding: "10px 12px", font: "inherit", color: "#241430",
        background: "#FAF7F2", border: `1.5px solid ${accent}`, borderRadius: 8,
      }} />
      <p id="fg-react-help-1" style={{ margin: "6px 0 0", fontSize: 12, color: "#24143099" }}>{helper}</p>
    </div>
  );
}
